// ===========================================================================
// Фикстура тестов слоёв и масок коллизий: .layerBits() / .mask() /
// .collidesWith() и фильтры запросов ($.world.raycast/bodyAt/bodiesIn).
//
// Сцена намеренно пустая: статичные стены разных слоёв (мишени для лучей и
// запросов) плюс точка отсчёта. Динамические тела создаёт сам тест — так в
// одном прогоне проверяются и «сталкиваются», и «не сталкиваются».
//
// Гранат нет: мировое притяжение выключено, и всё, что не толкается Box2D,
// стоит на месте — проверки не зависят от порядка шагов.
// ===========================================================================

$.ready(() => {
    $.world.gravity(0, 0).color('#101820').bounds(0, 0, 1280, 720);

    // Стена на слое 4: её видят только запросы с маской 4.
    $('<wall>', { id: 'wall4' }).at(300, 200).size(64, 64).layerBits(4).appendTo($.world);
    // Стена на слое 1 (умолчание движка).
    $('<wall>', { id: 'wall1' }).at(500, 200).size(64, 64).appendTo($.world);

    // Опора под «стоящими» телами: проверяем, что фильтр не мешает обычному
    // миру — тела на слое 2 встают на неё, тела с маской 0 падают сквозь.
    $('<wall>', { id: 'ground' }).at(900, 500).size(400, 32).layerBits(1).appendTo($.world);

    // Проём 20 px по вертикали (y 190..210): луч по центру проходит, объём
    // толщиной больше 20 px — нет. На этом и проверяется свип формы.
    $('<wall>', { id: 'gapTop' }).at(700, 180).size(40, 20).appendTo($.world);
    $('<wall>', { id: 'gapBottom' }).at(700, 220).size(40, 20).appendTo($.world);

    // Тонкая стена на слое 4 — цель свипа с маской.
    $('<wall>', { id: 'thin4' }).at(760, 200).size(16, 16).layerBits(4).appendTo($.world);

    // Отметка «сцена жива»: если упадёт кадр, тест это заметит.
    $('<rect>', { id: 'marker' }).at(20, 20).size(12, 12).color('#ffd34d').appendTo($.world);
});
